slides=[]
def S(title,blocks=None,sub='',take='',section='FOUNDATIONS',source='',kind='normal'):
 slides.append(dict(title=title,blocks=blocks or [],sub=sub,take=take,section=section,source=source,kind=kind))
def P(s):return ('p',s)
def B(s):return ('b',s)
def C(label,s,size=19):return ('code',label,s,size)
def M(tex):return ('math',tex)
def T(headers,rows,widths=None):return ('table',headers,rows,widths)
def Two(a,b):return ('two',a,b)
def Grid(inputs='',limit=25):return ('grid',inputs,limit)
def lines(s,n=42):return '\n'.join(s[i:i+n] for i in range(0,len(s),n))
def Partial(known):return C('PARTIAL PLAINTEXT • · = UNDETERMINED',lines(partial({x:DECODE[x] for x in known})))
def F(title,blocks=None,**kw):S(title,blocks,section='FREQUENCY ANALYSIS',**kw)
def V(title,blocks=None,**kw):S(title,blocks,section='VIGENÈRE',**kw)
def PF(title,blocks=None,**kw):S(title,blocks,section='PLAYFAIR',**kw)
def TR(title,blocks=None,**kw):S(title,blocks,section='TRANSPOSITION',**kw)

S('Classical ciphers',[P('An introduction to cryptography'),P('Historical constructions, mathematical definitions, and worked cryptanalysis.'),C('LECTURE 01','Master’s level • Mathematics')],sub='Cryptography lecture series',kind='cover',take='Three hours, including two 10-minute breaks • Revised edition')
